<script setup lang="ts">
import { IonContent, IonPage } from '@ionic/vue'

import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { storeToRefs } from 'pinia'
import type { CharacterVoiceItem } from '@/services/universe'
import { universeService } from '@/services/universe'
import CheckIcon from '@/components/svg/CheckIcon.vue'
import SoundWaveIcon from '@/components/svg/SoundWaveIcon.vue'
import SoundSpeakerIcon from '@/components/svg/SoundSpeakerIcon.vue'
import { useCreateUniverseStore } from '@/store/createUniverseStore'
import CommonHeader from '@/components/CommonHeader.vue'

const router = useRouter()
const createUniverseStore = useCreateUniverseStore()
const { inEditCharacter, generatedUniverse } = storeToRefs(createUniverseStore)
const charId = +router.currentRoute.value.params.id
const char = generatedUniverse.value?.chars.find(
  c => c?.charId === charId,
)
const allVoiceList = ref<CharacterVoiceItem[]>([])
const audio = ref<HTMLAudioElement | null>(null)
const playingVoiceId = ref(0)

async function play(id: number, url: string) {
  if (id === playingVoiceId.value) {
    audio.value?.pause()
  }
  else {
    audio.value?.pause()
    audio.value = new Audio(url)
    audio.value.onplay = () => {
      playingVoiceId.value = id
    }
    audio.value.onended = () => {
      playingVoiceId.value = 0
    }
    audio.value?.play()
  }
}

function onSelectVoice(voice: CharacterVoiceItem) {
  if (inEditCharacter.value) {
    inEditCharacter.value.voice = voice.voiceId
  }
}

const languages = ['English', 'Japanese (coming soon)']

function onSelectLanguage(language: string) {
  // only support English for now
  // will modify the structure later
  if (language !== 'English') {
    return
  }

  // find the character
  if (inEditCharacter.value) {
    inEditCharacter.value.language = language
  }
}

onMounted(async () => {
  const res = await universeService.getVoiceList(
    inEditCharacter.value?.voice || char?.voice || 0,
  )
  allVoiceList.value = res
})
</script>

<template>
  <ion-page>
    <common-header title="Voice Setting">
      <div class="w-8" />
    </common-header>
    <ion-content>
      <div>
        <div class="card">
          <!-- <div class="title">
            Matched character
          </div> -->
          <div class="title">
            All Voice
          </div>
          <div>
            <div
              v-for="voice in allVoiceList"
              :key="voice?.voiceId"
              class="item"
              @click="
                () => {
                  onSelectVoice(voice);
                }
              "
            >
              <div class="flex flex-1 justify-between items-center">
                <div class="flex flex-1 gap-2 items-center">
                  <check-icon
                    v-if="
                      inEditCharacter?.voice
                        ? inEditCharacter.voice === voice.voiceId
                        : voice.voiceId === char?.voice
                    "
                  />
                  {{ voice.displayName }}
                </div>
                <div
                  class="sound-play"
                  :style="
                    playingVoiceId === voice?.voiceId
                      ? 'background-color: #00F4FF'
                      : ''
                  "
                  @click="() => play(voice?.voiceId, voice.sampleUrl)"
                >
                  <sound-wave-icon v-if="playingVoiceId === voice?.voiceId" />
                  <sound-speaker-icon v-else />
                  {{ voice?.duration }}”
                </div>
              </div>
            </div>
          </div>
        </div>
        <div class="card">
          <div class="title">
            Voice Language
          </div>
          <div v-for="(language, index) in languages" :key="language">
            <div
              :class="`item ${index === 1 ? 'opacity-50' : ''}`"
              @click="
                () => {
                  onSelectLanguage(language);
                }
              "
            >
              <check-icon v-if="char?.language === language" />
              {{ language }}
            </div>
          </div>
        </div>
      </div>
    </ion-content>
  </ion-page>
</template>

